    def _emit_builtin_round(self, node):
        if len(node.args) == 1:
            # Use FV dispatch to handle bridge float values stored as i64
            fv = self._load_or_wrap_fv(node.args[0])
            tag = self.builder.extract_value(fv, 0)
            data = self.builder.extract_value(fv, 1)
            is_float = self.builder.icmp_signed(
                "==", tag, ir.Constant(i32, FPY_TAG_FLOAT))
            as_float = self.builder.bitcast(data, double)
            as_int_float = self.builder.sitofp(data, double)
            val = self.builder.select(is_float, as_float, as_int_float)
            # round(int) should return int; round(float) uses runtime
            # For simplicity, always go through round() runtime
            return self.builder.call(self.runtime["round"], [val])
        if len(node.args) == 2:
            # Use FV dispatch for runtime-tag-aware float detection
            fv = self._load_or_wrap_fv(node.args[0])
            tag = self.builder.extract_value(fv, 0)
            data = self.builder.extract_value(fv, 1)
            ndigits = self._emit_expr_value(node.args[1])
            is_float = self.builder.icmp_signed(
                "==", tag, ir.Constant(i32, FPY_TAG_FLOAT))
            as_float = self.builder.bitcast(data, double)
            as_int_float = self.builder.sitofp(data, double)
            val = self.builder.select(is_float, as_float, as_int_float)
            result_double = self.builder.call(
                self.runtime["round_ndigits"], [val, ndigits])
            # Python: round(int, ndigits) → int; round(float, ndigits) → float.
            # Preserve the input type in the returned FpyValue tag.
            result_int_data = self.builder.fptosi(result_double, i64)
            result_float_data = self.builder.bitcast(result_double, i64)
            result_data = self.builder.select(
                is_float, result_float_data, result_int_data)
            result_tag = self.builder.select(
                is_float,
                ir.Constant(i32, FPY_TAG_FLOAT),
                ir.Constant(i32, FPY_TAG_INT))
            return self._fv_build_from_slots(result_tag, result_data)
        raise CodeGenError("round() takes 1 or 2 arguments", node)

    def _emit_builtin_repr(self, node):
        if len(node.args) == 1:
            arg_node = node.args[0]
            # Exception variable: repr(e) → "ExcName('msg')"
            if (isinstance(arg_node, ast.Name)
                    and arg_node.id in self._exc_vars):
                cls_name = self._exc_vars[arg_node.id]
                msg = self._emit_expr_value(arg_node)
                msg = self._ensure_ptr(msg)
                prefix = self._make_string_constant(f"{cls_name}('")
                suffix = self._make_string_constant("')")
                tmp = self.builder.call(
                    self.runtime["str_concat"], [prefix, msg])
                return self.builder.call(
                    self.runtime["str_concat"], [tmp, suffix])
            # OBJ fast path: use obj_to_repr which handles
            # __repr__ → __str__ → default fallback safely
            if self._is_obj_expr(arg_node):
                obj = self._emit_expr_value(arg_node)
                obj = self._ensure_ptr(obj)
                result = self.builder.call(
                    self.runtime["obj_to_repr"], [obj])
                return self._ensure_ptr(result)
            # Use FV dispatch so runtime tag drives the conversion.
            fv = self._load_or_wrap_fv(node.args[0])
            # Model-2: fastpy_fv_repr always allocates a fresh owned buffer
            # (even for str input — it adds quotes), so its result is always
            # owned. Register it for release at the statement boundary.
            return self._register_owned_str_ptr(self._fv_call_repr(fv))
        raise CodeGenError("repr() takes exactly one argument", node)

    def _emit_builtin_sum(self, node):
        # Phase 2: use TypedValue to accept lists, tuples, and sets
        # Object expression (e.g. generator call) — materialize to list
        # first so the index-based sum loop works correctly.
        if (len(node.args) >= 1
                and self._is_obj_expr(node.args[0])):
            obj = self._emit_expr_value(node.args[0])
            obj = self._ensure_ptr(obj)
            lst = self._rt_call("list_from_obj_iter", [obj])
            # Wrap as a list-typed TypedValue so the sum path works
            tv_sum = TypedValue(lst, ValueType(VKind.LIST))
            sum_kind = VKind.LIST
        else:
            tv_sum = self._emit_expr(node.args[0]) if node.args else None
            sum_kind = tv_sum.vtype.kind if tv_sum else VKind.UNKNOWN
        is_iterable = (sum_kind in (VKind.LIST, VKind.TUPLE, VKind.SET)
                       or self._is_list_expr(node.args[0]) if node.args else False)
        if len(node.args) >= 1 and is_iterable:
            # Convert set to list first
            if sum_kind == VKind.SET:
                lst = self._rt_call("set_to_list",
                                    [tv_sum.as_ptr(self.builder)])
            else:
                lst = tv_sum.as_ptr(self.builder)
            length = self._rt_call("list_length", [lst])

            # Determine element type: float elements need fadd
            _sum_float = False
            _elems_are_float = False  # whether list elements are float
            if len(node.args) >= 1:
                _elem = self._get_list_elem_type(node.args[0])
                if _elem.kind == VKind.FLOAT:
                    _sum_float = True
                    _elems_are_float = True
            # Also detect dict.values() with float values by checking
            # the dict literal
            if (not _sum_float and len(node.args) >= 1
                    and isinstance(node.args[0], ast.Call)
                    and isinstance(node.args[0].func, ast.Attribute)
                    and node.args[0].func.attr == "values"):
                _dv = self._infer_dict_value_kind(node.args[0].func.value)
                if _dv == VKind.FLOAT:
                    _sum_float = True
                    _elems_are_float = True
            # float start value also triggers float mode
            if (not _sum_float and len(node.args) >= 2
                    and isinstance(node.args[1], ast.Constant)
                    and isinstance(node.args[1].value, float)):
                _sum_float = True

            # Heap-numeric elements need an FpyValue accumulator.  Both loops
            # below read the element with `_list_get_as_bare(..., "int")`,
            # which throws the runtime tag away and keeps the raw i64 — for a
            # BigInt, Decimal or complex that i64 is the value's *address*, so
            # `sum([2 ** 80, 2 ** 80])` added two pointers and printed
            # `4413044692288`.  BUG-SUM-BARE-I64-OVER-HEAP-ELEMENTS.
            #
            # FVALUE/MIXED elements have the same problem for a different
            # reason: nothing is statically known about them, so the bare read
            # is a guess that is wrong for every float element too.
            #
            # The third accumulator keeps (tag, data) and folds with
            # `fastpy_fv_binop`, which is the one place that knows how to add
            # every tag combination — and, being the same helper the binop
            # paths use, it also raises the right TypeError for `sum(["a"])`
            # instead of silently adding two string pointers.
            _sum_fv = False
            if not _sum_float and len(node.args) >= 1:
                _fv_kinds = (VKind.BIGINT, VKind.DECIMAL, VKind.COMPLEX,
                             VKind.FVALUE, VKind.MIXED)
                if self._get_list_elem_type(node.args[0]).kind in _fv_kinds:
                    _sum_fv = True

            if _sum_fv:
                _acc_tag = self._create_entry_alloca(i32, "sumfv.tag")
                _acc_data = self._create_entry_alloca(i64, "sumfv.data")
                if len(node.args) >= 2:
                    _st = self._emit_expr(node.args[1])
                    _stag, _sdata = self._fv_unpack(_st.as_fv(self.builder))
                    self.builder.store(_stag, _acc_tag)
                    self.builder.store(_sdata, _acc_data)
                else:
                    self.builder.store(ir.Constant(i32, FPY_TAG_INT), _acc_tag)
                    self.builder.store(ir.Constant(i64, 0), _acc_data)

                idx_alloca = self._create_entry_alloca(i64, "sum.idx")
                self.builder.store(ir.Constant(i64, 0), idx_alloca)
                cond_block = self._new_block("sumfv.cond")
                body_block = self._new_block("sumfv.body")
                end_block = self._new_block("sumfv.end")
                self.builder.branch(cond_block)
                self.builder.position_at_end(cond_block)
                idx = self.builder.load(idx_alloca)
                self.builder.cbranch(
                    self.builder.icmp_signed("<", idx, length),
                    body_block, end_block)

                self.builder.position_at_end(body_block)
                idx = self.builder.load(idx_alloca)
                _etag, _edata = self._fv_list_get(lst, idx, "sumfv.elem")
                self._rt_call(
                    "fv_binop",
                    [self.builder.load(_acc_tag),
                     self.builder.load(_acc_data), _etag, _edata,
                     ir.Constant(i32, self._FV_BINOP_OPCODES[ast.Add]),
                     _acc_tag, _acc_data])
                self._emit_try_bail_if_exc()
                self.builder.store(
                    self.builder.add(idx, ir.Constant(i64, 1)), idx_alloca)
                self.builder.branch(cond_block)

                self.builder.position_at_end(end_block)
                return self._fv_build_from_slots(self.builder.load(_acc_tag),
                                                 self.builder.load(_acc_data))

            if _sum_float:
                sum_alloca = self._create_entry_alloca(double, "sum.acc")
                if len(node.args) >= 2:
                    start_val = self._emit_expr_value(node.args[1])
                    if isinstance(start_val.type, ir.IntType):
                        start_val = self.builder.sitofp(start_val, double)
                    self.builder.store(start_val, sum_alloca)
                else:
                    self.builder.store(ir.Constant(double, 0.0), sum_alloca)
            else:
                sum_alloca = self._create_entry_alloca(i64, "sum.acc")
                if len(node.args) >= 2:
                    start_val = self._emit_expr_value(node.args[1])
                    self.builder.store(start_val, sum_alloca)
                else:
                    self.builder.store(ir.Constant(i64, 0), sum_alloca)

            idx_alloca = self._create_entry_alloca(i64, "sum.idx")
            self.builder.store(ir.Constant(i64, 0), idx_alloca)

            cond_block = self._new_block("sum.cond")
            body_block = self._new_block("sum.body")
            end_block = self._new_block("sum.end")

            self.builder.branch(cond_block)
            self.builder.position_at_end(cond_block)
            idx = self.builder.load(idx_alloca)
            cond = self.builder.icmp_signed("<", idx, length)
            self.builder.cbranch(cond, body_block, end_block)

            self.builder.position_at_end(body_block)
            idx = self.builder.load(idx_alloca)
            if _sum_float:
                if _elems_are_float:
                    elem = self._list_get_as_bare(lst, idx, "float")
                else:
                    # Elements are ints but accumulator is float —
                    # read as int and convert to float
                    elem_int = self._list_get_as_bare(lst, idx, "int")
                    elem = self.builder.sitofp(elem_int, double)
                acc = self.builder.load(sum_alloca)
                self.builder.store(self.builder.fadd(acc, elem), sum_alloca)
            else:
                elem = self._list_get_as_bare(lst, idx, "int")
                acc = self.builder.load(sum_alloca)
                self.builder.store(self.builder.add(acc, elem), sum_alloca)
            self.builder.store(self.builder.add(idx, ir.Constant(i64, 1)), idx_alloca)
            self.builder.branch(cond_block)

            self.builder.position_at_end(end_block)
            return self.builder.load(sum_alloca)
        return self._bridge_fallback_expr(node, "sum() with non-list argument")

    def _emit_builtin_set(self, node):
        if len(node.args) == 1:
            arg_node = node.args[0]
            # set(str) → set of single-char strings: convert str→list first
            _is_str = False
            if isinstance(arg_node, ast.Constant) and isinstance(arg_node.value, str):
                _is_str = True
            elif isinstance(arg_node, ast.Name) and arg_node.id in self.variables:
                _is_str = (self._var_kind(arg_node.id) == VKind.STR)
            if _is_str:
                s = self._emit_expr_value(arg_node)
                s = self._ensure_ptr(s)
                lst = self.builder.call(self.runtime["str_to_list"], [s])
                return self._rt_call("set_from_list", [lst])
            # set(pyobj) → iterate CPython iterable into list, then to set
            _is_pyobj = False
            if isinstance(arg_node, ast.Name) and arg_node.id in self.variables:
                _is_pyobj = self._var_kind(arg_node.id) == VKind.PYOBJ
            if not _is_pyobj:
                _is_pyobj = self._is_pyobj_receiver(
                    arg_node, include_native_mod=False)
            if _is_pyobj:
                val = self._emit_expr_value(arg_node)
                lst = self._pyobj_to_list(val)
                return self._rt_call("set_from_list", [lst])
            # set(obj) — materialize via __iter__/__next__
            if self._is_obj_expr(arg_node):
                obj = self._emit_expr_value(arg_node)
                obj = self._ensure_ptr(obj)
                lst = self._rt_call("list_from_obj_iter", [obj])
                return self._rt_call("set_from_list", [lst])
            # Everything else goes through the runtime on its tag.  This used
            # to hand the argument's bare pointer to `set_from_list`, which
            # reads it as an FpyList -- so `set({"k": 1})`, `set(b"AB")` and
            # `set({7, 8})` each read one container type through another's
            # field offsets and died, the constructor half of
            # BUG-SET-UPDATE-NON-SET-ITERABLE-SEGFAULTS.  Only the FpyValue
            # case was routed by tag, which is why the bug was invisible
            # wherever the compiler had *failed* to pin the kind down and
            # visible wherever it had succeeded.
            arg = self._emit_expr_value(arg_node)
            tag, data = self._to_tag_data_ir(arg, arg_node)
            # `_to_tag_data_ir` answers STR for a pointer whose kind it could
            # not infer -- a default, not a fact.  This call site's default has
            # always been LIST, and `set(<a list>)` is what an un-inferred
            # pointer overwhelmingly is, so keep it: the point of this change
            # is to stop guessing where the kind is *known*, not to give the
            # unknown case a new way to be wrong.
            if (isinstance(tag, ir.Constant)
                    and int(tag.constant) == FPY_TAG_STR
                    and self._infer_type_tag(arg_node, arg).kind != VKind.STR):
                tag = ir.Constant(i32, FPY_TAG_LIST)
            return self.builder.call(
                self.runtime["set_from_iterable_fv"], [tag, data])
        if len(node.args) == 0:
            return self.builder.call(self.runtime["dict_new"], [])
        raise CodeGenError("set() takes 0 or 1 arguments", node)

    def _emit_builtin_min(self, node):
        # Resolve which builtin (min or max) from the call node
        name = node.func.id if isinstance(node.func, ast.Name) else "min"
        # Extract key= kwarg if provided. Supports `key=len` (for
        # strings) and `key=<user_function>` that returns int.
        key_func_name: str | None = None
        key_func_ptr = None  # for lambda/closure keys
        for kw in node.keywords:
            if kw.arg == "key":
                if isinstance(kw.value, ast.Name):
                    key_func_name = kw.value.id
                elif isinstance(kw.value, ast.Lambda):
                    # Compile lambda as i64(i64) function pointer
                    key_func_ptr = self._get_unary_func_ptr(kw.value, node)
                    key_func_name = "__lambda__"
        # Object expression (e.g. generator call): materialize to list
        if (len(node.args) == 1
                and self._is_obj_expr(node.args[0])):
            obj = self._emit_expr_value(node.args[0])
            obj = self._ensure_ptr(obj)
            lst = self._rt_call("list_from_obj_iter", [obj])
            tv_mm = TypedValue(lst, ValueType(VKind.LIST))
            mm_kind = VKind.LIST
        else:
            # Phase 2: use TypedValue to also accept tuples and sets
            tv_mm = self._emit_expr(node.args[0]) if len(node.args) == 1 else None
            mm_kind = tv_mm.vtype.kind if tv_mm else VKind.UNKNOWN
        mm_ok = (mm_kind in (VKind.LIST, VKind.TUPLE, VKind.SET)
                 or (len(node.args) == 1 and self._is_list_expr(node.args[0])))
        if len(node.args) == 1 and mm_ok:
            if mm_kind == VKind.SET:
                lst = self._rt_call("set_to_list",
                                    [tv_mm.as_ptr(self.builder)])
            else:
                lst = tv_mm.as_ptr(self.builder) if tv_mm else \
                      self._emit_expr_value(node.args[0])
            length = self._rt_call("list_length", [lst])
            elem_type = self._get_list_elem_type(node.args[0])
            is_str = (elem_type.kind == VKind.STR)
            is_ptr = elem_type.kind.is_ptr
            result_type = i8_ptr if is_ptr else i64
            bare_tag = str(elem_type) if is_ptr else "int"

            # OBJ elements: use runtime min/max that dispatches
            # to __lt__ — no need for our own loop
            if elem_type.kind == VKind.OBJ:
                rt_name = "list_min_fv" if name == "min" else "list_max_fv"
                data_i64 = self.builder.call(self.runtime[rt_name], [lst])
                return self._ensure_ptr(data_i64)

            result_alloca = self._create_entry_alloca(result_type, f"{name}.result")
            first = self._list_get_as_bare(
                lst, ir.Constant(i64, 0), bare_tag)
            self.builder.store(first, result_alloca)

            def _apply_key(e):
                """Apply the key function to an element, returning i64."""
                if key_func_name is None:
                    return e
                elif key_func_name == "__lambda__":
                    # Call through function pointer
                    fn_typed = self.builder.bitcast(
                        key_func_ptr,
                        ir.PointerType(ir.FunctionType(i64, [i64])))
                    arg = e
                    if isinstance(e.type, ir.PointerType):
                        arg = self.builder.ptrtoint(e, i64)
                    return self.builder.call(fn_typed, [arg])
                elif key_func_name == "len":
                    # len on strings returns int64
                    if isinstance(e.type, ir.PointerType):
                        return self.builder.call(
                            self.runtime["str_len"], [e])
                    if isinstance(e.type, ir.IntType):
                        return self.builder.call(
                            self.runtime["list_length"], [
                                self._ensure_ptr(e)])
                    return ir.Constant(i64, 0)
                elif key_func_name == "abs":
                    neg = self.builder.neg(e)
                    is_neg = self.builder.icmp_signed(
                        "<", e, ir.Constant(i64, 0))
                    return self.builder.select(is_neg, neg, e)
                # User function call
                elif key_func_name in self._user_functions:
                    info = self._user_functions[key_func_name]
                    fv = self._wrap_arg_value(e, None)
                    ret = self.builder.call(info.func, [fv])
                    if info.uses_fv_abi:
                        return self._unwrap_return_value(ret, info)
                    return ret
                return e

            # Track the best *key value*, but return the original
            # element. Store both key-of-best and best-element.
            # Only create key_alloca when a key= was specified.
            key_alloca = None
            if key_func_name is not None:
                key_alloca = self._create_entry_alloca(
                    i64, f"{name}.keybest")
                first_key = _apply_key(first)
                if first_key.type != i64:
                    if isinstance(first_key.type, ir.IntType):
                        first_key = self.builder.zext(first_key, i64)
                self.builder.store(first_key, key_alloca)
            idx_alloca = self._create_entry_alloca(i64, f"{name}.idx")
            self.builder.store(ir.Constant(i64, 1), idx_alloca)

            cond_block = self._new_block(f"{name}.cond")
            body_block = self._new_block(f"{name}.body")
            end_block = self._new_block(f"{name}.end")

            self.builder.branch(cond_block)
            self.builder.position_at_end(cond_block)
            idx = self.builder.load(idx_alloca)
            cond = self.builder.icmp_signed("<", idx, length)
            self.builder.cbranch(cond, body_block, end_block)

            self.builder.position_at_end(body_block)
            idx = self.builder.load(idx_alloca)
            current = self.builder.load(result_alloca)
            if key_func_name is not None:
                elem = self._list_get_as_bare(lst, idx, bare_tag)
                elem_key = _apply_key(elem)
                if elem_key.type != i64 and isinstance(elem_key.type, ir.IntType):
                    elem_key = self.builder.zext(elem_key, i64)
                best_key = self.builder.load(key_alloca)
                op = "<" if name == "min" else ">"
                is_better = self.builder.icmp_signed(op, elem_key, best_key)
                # Update best key and element
                new_key = self.builder.select(is_better, elem_key, best_key)
                self.builder.store(new_key, key_alloca)
                new_elem = self.builder.select(is_better, elem, current)
                self.builder.store(new_elem, result_alloca)
            elif is_str:
                elem = self._list_get_as_bare(lst, idx, "str")
                cmp_result = self._rt_call("str_compare", [elem, current])
                op = "<" if name == "min" else ">"
                is_better = self.builder.icmp_signed(op, cmp_result, ir.Constant(i64, 0))
                new_val = self.builder.select(is_better, elem, current)
                self.builder.store(new_val, result_alloca)
            else:
                elem = self._list_get_as_bare(lst, idx, "int")
                op = "<" if name == "min" else ">"
                is_better = self.builder.icmp_signed(op, elem, current)
                new_val = self.builder.select(is_better, elem, current)
                self.builder.store(new_val, result_alloca)
            self.builder.store(self.builder.add(idx, ir.Constant(i64, 1)), idx_alloca)
            self.builder.branch(cond_block)

            self.builder.position_at_end(end_block)
            return self.builder.load(result_alloca)
        if len(node.args) >= 2:
            # min/max with multiple inline args: min(a, b, c, ...)
            # Check if all args have the same type to decide dispatch.
            args = [self._emit_expr_value(a) for a in node.args]
            all_same_type = all(
                type(a.type) == type(args[0].type)  # noqa: E721
                and (not isinstance(a.type, ir.IntType)
                     or a.type.width == args[0].type.width)
                for a in args[1:]
            )
            if all_same_type:
                # Homogeneous types: direct compare + select
                result = args[0]
                op = "<" if name == "min" else ">"
                for other in args[1:]:
                    if isinstance(result.type, ir.DoubleType):
                        is_better = self.builder.fcmp_ordered(op, other, result)
                    else:
                        is_better = self.builder.icmp_signed(op, other, result)
                    result = self.builder.select(is_better, other, result)
                return result
            # Mixed types (e.g. min(float, int)): Python returns the original
            # value preserving its type.  Use FpyValue to track each arg's type,
            # compare with promotion, and return the winner's original FpyValue.
            op = "<" if name == "min" else ">"
            # Wrap first arg in FpyValue
            result_fv = self._wrap_for_print(args[0], node.args[0])
            for i, other_val in enumerate(args[1:]):
                other_fv = self._wrap_for_print(other_val, node.args[i + 1])
                # Promote both to double for comparison
                cmp_a = args[0] if i == 0 else self._fv_data_i64(result_fv)
                cmp_b = other_val
                # For comparison: both as double
                a_dbl = (cmp_a if isinstance(cmp_a.type, ir.DoubleType)
                         else self.builder.sitofp(
                             cmp_a if isinstance(cmp_a.type, ir.IntType)
                             else self._fv_data_i64(result_fv), double))
                b_dbl = (cmp_b if isinstance(cmp_b.type, ir.DoubleType)
                         else self.builder.sitofp(cmp_b, double))
                is_better = self.builder.fcmp_ordered(op, b_dbl, a_dbl)
                # Select the winner's FpyValue (preserving original type tag)
                result_fv = self.builder.select(is_better, other_fv, result_fv)
            return result_fv
        return self._bridge_fallback_expr(node, f"{name}() with unsupported args")


    # -- _emit_call_expr helpers ------------------------------------

    def _emit_static_method_call(self, node: ast.Call):
        """Handle static method calls: str.maketrans, int.from_bytes,
        dict.fromkeys.  Returns the result or None if not matched."""
        cls_name = node.func.value.id
        method = node.func.attr
        if cls_name == "str" and method == "maketrans" and len(node.args) == 2:
            from_chars = self._emit_expr_value(node.args[0])
            to_chars = self._emit_expr_value(node.args[1])
            return self._rt_call("str_maketrans", [from_chars, to_chars])
        elif cls_name == "int" and method == "from_bytes" and len(node.args) >= 2:
            b = self._emit_expr_value(node.args[0])
            byteorder = self._emit_expr_value(node.args[1])
            blen = self._rt_call("str_len", [b])
            return self._rt_call("int_from_bytes", [b, blen, byteorder])
        elif cls_name == "dict" and method == "fromkeys":
            if len(node.args) == 1:
                keys = self._emit_expr_value(node.args[0])
                return self._rt_call("dict_fromkeys_none", [keys])
            if len(node.args) == 2:
                keys = self._emit_expr_value(node.args[0])
                val = self._emit_expr_value(node.args[1])
                tag_ir, data_ir = self._to_tag_data_ir(val, node.args[1])
                return self._rt_call("dict_fromkeys", [keys, tag_ir, data_ir])
        return None

    def _emit_unknown_builtin_call(self, node: ast.Call,
                                   name: str) -> ir.Value:
        """Route an unknown builtin (bytearray, frozenset, slice, complex,
        etc.) through the CPython bridge."""
        builtin_name = self._make_string_constant("builtins")
        builtins_mod = self.builder.call(
            self.runtime["cpython_import"], [builtin_name])
        func_name = self._make_string_constant(name)
        callable_ptr = self.builder.call(
            self.runtime["cpython_getattr"],
            [builtins_mod, func_name])
        out_tag = self._create_entry_alloca(i32, "pyblt.tag")
        out_data = self._create_entry_alloca(i64, "pyblt.data")
        n_args = len(node.args)
        if n_args == 0:
            self.builder.call(self.runtime["cpython_call0"],
                              [callable_ptr, out_tag, out_data])
        elif n_args == 1:
            arg = self._emit_expr_value(node.args[0])
            t_ir, d_ir = self._to_bridge_tag_data_ir(arg, node.args[0])
            self.builder.call(self.runtime["cpython_call1"],
                              [callable_ptr,
                               t_ir, d_ir,
                               out_tag, out_data])
        elif n_args == 2:
            a1 = self._emit_expr_value(node.args[0])
            t1_ir, d1_ir = self._to_bridge_tag_data_ir(a1, node.args[0])
            a2 = self._emit_expr_value(node.args[1])
            t2_ir, d2_ir = self._to_bridge_tag_data_ir(a2, node.args[1])
            self.builder.call(self.runtime["cpython_call2"],
                              [callable_ptr,
                               t1_ir, d1_ir,
                               t2_ir, d2_ir,
                               out_tag, out_data])
        elif n_args == 3:
            a1 = self._emit_expr_value(node.args[0])
            t1_ir, d1_ir = self._to_bridge_tag_data_ir(a1, node.args[0])
            a2 = self._emit_expr_value(node.args[1])
            t2_ir, d2_ir = self._to_bridge_tag_data_ir(a2, node.args[1])
            a3 = self._emit_expr_value(node.args[2])
            t3_ir, d3_ir = self._to_bridge_tag_data_ir(a3, node.args[2])
            self.builder.call(self.runtime["cpython_call3"],
                              [callable_ptr,
                               t1_ir, d1_ir,
                               t2_ir, d2_ir,
                               t3_ir, d3_ir,
                               out_tag, out_data])
        else:
            # 4+ args: use call_kw with 0 kwargs
            tags_alloca = self.builder.alloca(ir.ArrayType(i32, n_args))
            data_alloca = self.builder.alloca(ir.ArrayType(i64, n_args))
            for i, arg_node in enumerate(node.args):
                val = self._emit_expr_value(arg_node)
                t_ir, d_ir = self._to_bridge_tag_data_ir(val, arg_node)
                tp = self.builder.gep(tags_alloca, [ir.Constant(i64, 0), ir.Constant(i32, i)])
                self.builder.store(t_ir, tp)
                dp = self.builder.gep(data_alloca, [ir.Constant(i64, 0), ir.Constant(i32, i)])
                self.builder.store(d_ir, dp)
            t_ptr = self.builder.gep(tags_alloca, [ir.Constant(i64, 0), ir.Constant(i32, 0)])
            d_ptr = self.builder.gep(data_alloca, [ir.Constant(i64, 0), ir.Constant(i32, 0)])
            kn = ir.Constant(ir.PointerType(i8_ptr), None)
            kt = ir.Constant(ir.PointerType(i32), None)
            kd = ir.Constant(ir.PointerType(i64), None)
            self.builder.call(self.runtime["cpython_call_kw"],
                              [callable_ptr, ir.Constant(i32, n_args),
                               t_ptr, d_ptr, ir.Constant(i32, 0),
                               kn, kt, kd, out_tag, out_data])
        ret_tag = self.builder.load(out_tag)
        ret_data = self.builder.load(out_data)
        return self._fv_build_from_slots(ret_tag, ret_data)

    def _emit_set_arg_tags(self, pairs):
        """Publish the runtime tag of each positional argument.

        A callee whose parameter is UNKNOWN receives only a bare i64 and
        recovers the tag from the `fastpy_{set,get}_arg_tag` side-channel.
        That channel is *global and sticky*: a call site that forgets to
        write it leaves the previous call's tags in place, so the callee
        reads a stale tag and misinterprets its own argument.  Every site
        that reaches a Python-level function through a bare-i64 signature
        must therefore call this, even when the tag looks statically
        obvious — "obvious" only describes what the caller passes, not
        what the callee will read if we stay silent.

        `pairs` is a sequence of `(value, arg_node)`; `value` should be the
        argument *before* any ptrtoint/zext coercion, so `_bare_to_tag_data`
        still sees its real LLVM type.
        """
        for _ati, (_atv, _at_node) in enumerate(pairs):
            _rt_tag_val = None
            if (isinstance(_at_node, ast.Name)
                    and _at_node.id in self.variables):
                _v_alloca, _ = self.variables[_at_node.id]
                if (isinstance(_v_alloca.type, ir.PointerType)
                        and _v_alloca.type.pointee is fpy_val):
                    _fv_load = self.builder.load(
                        _v_alloca, name=f"fv.{_at_node.id}")
                    _rt_tag_val = self.builder.extract_value(
                        _fv_load, 0, name=f"fv.{_at_node.id}.tag")
            if (_rt_tag_val is None
                    and isinstance(_atv.type, ir.LiteralStructType)
                    and _atv.type == fpy_val):
                _rt_tag_val = self.builder.extract_value(_atv, 0)
            if _rt_tag_val is not None:
                self.builder.call(self.runtime["set_arg_tag"],
                                  [ir.Constant(i32, _ati), _rt_tag_val])
            else:
                _at_tag, _ = self._bare_to_tag_data(_atv,
                                                    value_node=_at_node)
                self.builder.call(self.runtime["set_arg_tag"],
                                  [ir.Constant(i32, _ati),
                                   ir.Constant(i32, _at_tag)])

    def _resolve_dunder_call_func(self, cls_name):
        """Find the `__call__` LLVM function a class inherits, or None."""
        cn = cls_name
        while cn and cn in self._user_classes:
            ci = self._user_classes[cn]
            if "__call__" in ci.methods:
                return ci.methods["__call__"]
            cn = ci.parent_name
        return None

    def _emit_direct_dunder_call(self, obj_ptr, call_func, node: ast.Call):
        """Call a statically-resolved `__call__` with `node`'s arguments.

        Used by every `obj(...)` shape whose class is known at compile time,
        whether the object comes from a variable (`f = F(); f(x)`) or straight
        out of a constructor (`F()(x)`).  Going direct rather than through the
        runtime's name-based `fastpy_obj_call_methodN` matters for three
        reasons: the dispatcher only has 0-, 1- and 2-argument shapes, it
        flattens every return type to a bare `i64`, and it forces the caller
        to guess the result's tag.  Here the callee's real LLVM signature is
        in hand, so arguments are coerced to it and the return tag is read
        back from the side-channel the method itself published.
        """
        direct_args = [obj_ptr]
        call_vals = []
        for i, arg_node in enumerate(node.args):
            val = self._emit_expr_value(arg_node)
            call_vals.append((val, arg_node))
            if 1 + i < len(call_func.args):
                expected = call_func.args[1 + i].type
                if val.type != expected:
                    if (isinstance(expected, ir.IntType)
                            and isinstance(val.type, ir.IntType)
                            and expected.width != val.type.width):
                        if expected.width > val.type.width:
                            val = self.builder.zext(val, expected)
                        else:
                            val = self.builder.trunc(val, expected)
                    elif (isinstance(expected, ir.IntType)
                            and isinstance(val.type, ir.PointerType)):
                        val = self.builder.ptrtoint(val, expected)
                    elif (isinstance(expected, ir.PointerType)
                            and isinstance(val.type, ir.IntType)):
                        val = self.builder.inttoptr(val, expected)
                    elif (isinstance(expected, ir.DoubleType)
                            and isinstance(val.type, ir.IntType)):
                        val = self.builder.bitcast(val, expected)
                    elif (isinstance(expected, ir.IntType)
                            and isinstance(val.type, ir.DoubleType)):
                        val = self.builder.bitcast(val, expected)
            direct_args.append(val)
        # Set arg tags so the callee knows runtime types
        self._emit_set_arg_tags(call_vals)
        result = self.builder.call(call_func, direct_args)
        ret_type = call_func.return_value.type
        if isinstance(ret_type, ir.VoidType):
            return ir.Constant(i64, 0)
        return self._wrap_with_ret_tag(result)

    def _wrap_with_ret_tag(self, result):
        """Rebuild an FpyValue from a bare scalar return using `get_ret_tag`.

        Only call this once the callee is known to *publish* a tag, since the
        channel is sticky and otherwise hands back some earlier call's value —
        the same trap `_recover_closure_ret_tag` documents.  Two lowerings
        qualify: `fastpy.class.*` methods, whose every `return <expr>` path
        calls `set_ret_tag` (see `_needs_ret_tag` in `_emit_return`), and
        `fastpy.closure.*` bodies, which do the same.

        Without it the caller assumes INT, so `Echo()("xyz")` prints the
        string's address.  BUG-CALL-ON-CALL-IGNORES-RET-TAG.
        """
        if (isinstance(result.type, ir.LiteralStructType)
                and result.type == fpy_val):
            return result
        ret_tag = self.builder.call(self.runtime["get_ret_tag"], [])
        if isinstance(result.type, ir.PointerType):
            data = self.builder.ptrtoint(result, i64)
        elif isinstance(result.type, ir.DoubleType):
            data = self.builder.bitcast(result, i64)
        elif isinstance(result.type, ir.IntType):
            data = (result if result.type.width == 64
                    else self.builder.sext(result, i64))
        else:
            return result
        return self._fv_build_from_slots(ret_tag, data)

    def _emit_call_on_call(self, node: ast.Call):
        """Handle Call-on-Call patterns: f(3)(5), C()(5), etc.
        The inner call might return a closure or an object with __call__.
        Returns the result or None if not matched."""
        callee = self._emit_expr_value(node.func)
        callee = self._ensure_ptr(callee)
        if not isinstance(callee.type, ir.PointerType):
            return None
        # Check if the inner call returns a closure
        inner_returns_closure = False
        # The callee's LLVM body, when the inner call resolves to a nested
        # def we generated.  Only then is `fpy_ret_tag` guaranteed fresh
        # after the indirect call — see `_wrap_with_ret_tag`.
        _closure_fn = None
        if isinstance(node.func.func, ast.Name):
            inner_name = node.func.func.id
            for full_name in self._closure_info:
                if full_name.startswith(f"{inner_name}."):
                    inner_returns_closure = True
                    _closure_fn = self.module.globals.get(
                        f"fastpy.closure.{full_name}")
                    break
            if (inner_name in self.variables
                    and self._var_kind(inner_name) == VKind.CLOSURE):
                inner_returns_closure = True

        def _tagged(res):
            return (self._wrap_with_ret_tag(res)
                    if _closure_fn is not None else res)

        if inner_returns_closure:
            # Use call_ptr dispatch (handles closures and raw func ptrs)
            n_args = len(node.args)
            if n_args == 0:
                return _tagged(self.builder.call(
                    self.runtime["call_ptr0"], [callee]))
            elif n_args == 1:
                a = self._emit_expr_value(node.args[0])
                self._emit_set_arg_tags([(a, node.args[0])])
                if isinstance(a.type, ir.PointerType):
                    a = self.builder.ptrtoint(a, i64)
                elif isinstance(a.type, ir.IntType) and a.type.width != 64:
                    a = self.builder.zext(a, i64)
                return _tagged(self.builder.call(
                    self.runtime["call_ptr1"], [callee, a]))
            elif n_args == 2:
                a1 = self._emit_expr_value(node.args[0])
                a2 = self._emit_expr_value(node.args[1])
                self._emit_set_arg_tags(
                    [(a1, node.args[0]), (a2, node.args[1])])
                if isinstance(a1.type, ir.PointerType):
                    a1 = self.builder.ptrtoint(a1, i64)
                if isinstance(a2.type, ir.PointerType):
                    a2 = self.builder.ptrtoint(a2, i64)
                return _tagged(self.builder.call(
                    self.runtime["call_ptr2"], [callee, a1, a2]))
        else:
            # Object with __call__.  When the inner call is a constructor of
            # a known user class the callee is statically resolvable, so go
            # direct — the runtime dispatcher below only has 0/1/2-argument
            # shapes and loses the return type.
            _ctor_cls = None
            if (isinstance(node.func, ast.Call)
                    and isinstance(node.func.func, ast.Name)
                    and node.func.func.id in self._user_classes):
                _ctor_cls = node.func.func.id
            if _ctor_cls is not None:
                _cf = self._resolve_dunder_call_func(_ctor_cls)
                if _cf is not None:
                    return self._emit_direct_dunder_call(callee, _cf, node)
            name_ptr = self._make_string_constant("__call__")
            if len(node.args) == 0:
                return self.builder.call(
                    self.runtime["obj_call_method0"],
                    [callee, name_ptr])
            elif len(node.args) == 1:
                a = self._emit_expr_value(node.args[0])
                # `C()(7)` reaches `__call__` through the runtime's
                # name-based dispatcher, which passes a bare i64 — so the
                # tag has to travel through the arg-tag channel or the
                # callee reads whatever the *previous* call left there.
                # BUG-CALL-ON-CALL-STALE-ARG-TAG.
                self._emit_set_arg_tags([(a, node.args[0])])
                if isinstance(a.type, ir.PointerType):
                    a = self.builder.ptrtoint(a, i64)
                elif isinstance(a.type, ir.IntType) and a.type.width != 64:
                    a = self.builder.zext(a, i64)
                return self.builder.call(
                    self.runtime["obj_call_method1"],
                    [callee, name_ptr, a])
        return None

    def _emit_call_expr(self, node: ast.Call) -> ir.Value:
        """Emit a function call as an expression (return value is used)."""
        # Namedtuple instance construction: P(3, 4) where P = namedtuple(...)
        if isinstance(node.func, ast.Name):
            _nt = getattr(self, '_namedtuple_types', {}).get(node.func.id)
            if _nt is not None:
                return self._emit_namedtuple_construct(node, _nt)
        # Rewrite bound-method aliases: f = lst.pop → f(0) becomes lst.pop(0)
        _bm_rewrite = self._rewrite_bound_method(node)
        if _bm_rewrite is not None:
            node = _bm_rewrite
        # Nested class constructor: Outer.Inner(args) where Inner is a
        # known user class.  Rewrite to a plain constructor call.
        if (isinstance(node.func, ast.Attribute)
                and isinstance(node.func.value, ast.Name)
                and node.func.value.id in self._user_classes
                and node.func.attr in self._user_classes):
            synth = ast.Call(
                func=ast.Name(id=node.func.attr, ctx=ast.Load()),
                args=node.args, keywords=node.keywords)
            return self._emit_constructor(synth)
        # Static method calls: str.maketrans, int.from_bytes, dict.fromkeys
        if (isinstance(node.func, ast.Attribute)
                and isinstance(node.func.value, ast.Name)):
            result = self._emit_static_method_call(node)
            if result is not None:
                return result
        # Native module method call: asyncio.run(), json.loads(), etc.
        if (isinstance(node.func, ast.Attribute)
                and isinstance(node.func.value, ast.Name)):
            _nm = node.func.value.id
            _is_native = ((self._has_var(_nm)
                          and self._var_kind(_nm) == VKind.PYOBJ)
                         or _nm in getattr(self, '_native_modules', set()))
            if _is_native:
                result = self._emit_native_module_call(
                    _nm, node.func.attr, node)
                if result is not None:
                    return result
                # Not natively handled — fall through to general method
                # call handler below, which routes through CPython bridge
                # via _emit_cpython_method_call when receiver is PYOBJ.
        # Chained native module call: os.path.exists(...), os.path.join(...)
        if (isinstance(node.func, ast.Attribute)
                and isinstance(node.func.value, ast.Attribute)
                and isinstance(node.func.value.value, ast.Name)):
            _nm = node.func.value.value.id
            _sub = node.func.value.attr
            _fn = node.func.attr
            _is_native = ((self._has_var(_nm)
                          and self._var_kind(_nm) == VKind.PYOBJ)
                         or _nm in getattr(self, '_native_modules', set()))
            if _is_native:
                # Try as "os.path" module with function "exists"
                combined = f"{_nm}.{_sub}"
                result = self._emit_native_module_call(combined, _fn, node)
                if result is not None:
                    return result
                # Not natively handled — fall through to general handler
        if isinstance(node.func, ast.Name):
            name = self._resolve_func_alias(node.func.id)
            # Native module function (from math import sqrt → sqrt(x))
            if name in getattr(self, '_native_imports', {}):
                mod, attr = self._native_imports[name]
                result = self._emit_native_module_call(mod, attr, node)
                if result is not None:
                    return result
            # Check for weakref dereference: r() where r = weakref.ref(obj)
            elif name in getattr(self, '_weakref_vars', set()):
                return self._emit_weakref_deref(node)
            # Check for closure variable or callable function pointer
            elif name in self.variables:
                _vk = self._var_kind(name)
                if _vk == VKind.CLOSURE:
                    result = self._emit_closure_call(node)
                    return self._recover_closure_ret_tag(name, result)
                # OBJ variable with __call__ → direct dispatch
                if _vk == VKind.OBJ:
                    _call_cls = self._obj_var_class.get(name)
                    if _call_cls and self._class_has_method(_call_cls, "__call__"):
                        obj = self._load_variable(name, node)
                        obj = self._ensure_ptr(obj)
                        call_func = self._resolve_dunder_call_func(_call_cls)
                        if call_func is not None:
                            return self._emit_direct_dunder_call(
                                obj, call_func, node)
                # FVALUE/MIXED/OBJ variables that might hold a function pointer:
                # dispatch through closure call path which uses call_ptr to
                # auto-detect closures vs raw function pointers at runtime.
                # Wrap the result in an FpyValue using the ret_tag side-channel
                # so the caller can dispatch on the actual return type (str,
                # int, float, etc.) rather than treating everything as i64.
                if _vk in (VKind.FVALUE, VKind.MIXED, VKind.OBJ):
                    result = self._emit_closure_call(node)
                    # _emit_closure_call may already return an FpyValue
                    # (e.g. kwargs path uses _fv_build_from_slots).
                    if (isinstance(result.type, ir.LiteralStructType)
                            and result.type == fpy_val):
                        return result
                    ret_tag = self.builder.call(
                        self.runtime["get_ret_tag"], [])
                    fv = ir.Constant(fpy_val, ir.Undefined)
                    fv = self.builder.insert_value(fv, ret_tag, 0)
                    if isinstance(result.type, ir.PointerType):
                        result = self.builder.ptrtoint(result, i64)
                    elif isinstance(result.type, ir.DoubleType):
                        result = self.builder.bitcast(result, i64)
                    elif (isinstance(result.type, ir.IntType)
                          and result.type.width != 64):
                        result = self.builder.zext(result, i64)
                    fv = self.builder.insert_value(fv, result, 1)
                    return fv
                if _vk == VKind.NATIVE_FUNC:
                    # Native function via from-import — if native handler didn't
                    # handle it (returned None above), fall through to bridge.
                    # Import the real module and call the function through CPython.
                    if name in getattr(self, '_native_imports', {}):
                        mod, attr = self._native_imports[name]
                        mod_ptr = self.builder.call(
                            self.runtime["cpython_import"],
                            [self._make_string_constant(mod)])
                        func_ptr = self.builder.call(
                            self.runtime["cpython_getattr"],
                            [mod_ptr, self._make_string_constant(attr)])
                        # Call it through the bridge
                        return self._emit_cpython_call_with_ptr(func_ptr, node)
                if _vk == VKind.PYOBJ:
                    # Call a CPython bridge object (class constructor, function, etc.)
                    # Re-fetch from module at call time to avoid stale pointers.
                    bridge_imports = getattr(self, '_bridge_imports', {})
                    if name in bridge_imports:
                        mod, attr = bridge_imports[name]
                        mod_ptr = self.builder.call(
                            self.runtime["cpython_import"],
                            [self._make_string_constant(mod)])
                        func_ptr = self.builder.call(
                            self.runtime["cpython_getattr"],
                            [mod_ptr, self._make_string_constant(attr)])
                        return self._emit_cpython_call_with_ptr(func_ptr, node)
                    return self._emit_cpython_direct_call_expr(node)
            # Module-level pyobj from-imports (e.g. Template, Context from
            # `from django.template import Context, Template`) accessible
            # inside functions without explicit `global` declaration.
            # _bridge_imports persists across function boundaries so we can
            # re-fetch the callable from the module at call time.
            bridge_imports = getattr(self, '_bridge_imports', {})
            if name not in self.variables and name in bridge_imports:
                mod, attr = bridge_imports[name]
                mod_ptr = self.builder.call(
                    self.runtime["cpython_import"],
                    [self._make_string_constant(mod)])
                func_ptr = self.builder.call(
                    self.runtime["cpython_getattr"],
                    [mod_ptr, self._make_string_constant(attr)])
                return self._emit_cpython_call_with_ptr(func_ptr, node)
            # Singledispatch: emit a switch on the first arg's runtime tag
            elif name in self._singledispatch and node.args:
                return self._emit_singledispatch_call(node, name)
            # lru_cache: wrap user function call with cache lookup
            lru_funcs = getattr(self, '_lru_cached_functions', {})
            if name in lru_funcs and name in self._user_functions:
                return self._emit_lru_cached_call(node, name)
            elif name in self._user_functions:
                result = self._emit_user_call(node)
                if result is None:
                    # Phase 4: None-returning function used as expression → 0
                    return ir.Constant(i64, 0)
                return result
            elif name in self._user_classes:
                return self._emit_constructor(node)
            # Builtin dispatch via registry
            handler_name = self._BUILTIN_DISPATCH.get(name)
            if handler_name:
                return getattr(self, handler_name)(node)

        # Unknown builtins: route through CPython bridge
        # This handles bytearray(), frozenset(), slice(), complex(), etc.
        if isinstance(node.func, ast.Name):
            name = node.func.id
            if (name not in self._user_functions
                    and name not in self._user_classes
                    and name not in self.variables
                    and name not in getattr(self, '_bridge_imports', {})):
                return self._emit_unknown_builtin_call(node, name)

        # Method calls like s.lower(), obj.speak()
        if isinstance(node.func, ast.Attribute):
            # Native module call: math.sqrt(x) → direct C libm call
            if (isinstance(node.func.value, ast.Name)
                    and node.func.value.id in self.variables
                    and self._var_kind(node.func.value.id) == VKind.PYOBJ):
                result = self._emit_native_module_call(
                    node.func.value.id, node.func.attr, node)
                if result is not None:
                    return result

            # CPython module method call: os.getcwd(), json.dumps(x), etc.
            # Check if the receiver is a pyobj variable or a chained
            # attribute access on a pyobj (e.g. os.path → Attribute on os).
            receiver_is_pyobj = self._is_pyobj_receiver(node.func.value)
            if receiver_is_pyobj:
                fv = self._emit_cpython_method_call(node)
                # Return the full FpyValue so the runtime tag is preserved.
                # Callers that need a bare type (print, assignment, len, etc.)
                # can dispatch on the tag.  The old code stripped the tag and
                # returned raw i64 — wrong for STR/LIST/DICT results from
                # bridge method calls like platform.system() or t.render(ctx).
                return fv
            return self._emit_method_call(node)
        # Direct pyobj call: func(args) where func is pyobj-tagged
        if (isinstance(node.func, ast.Name)
                and node.func.id in self.variables
                and self._var_kind(node.func.id) == VKind.PYOBJ):
            fv = self._emit_cpython_direct_call_expr(node)
            data = self.builder.extract_value(fv, 1)
            return data
        # Call-on-Call: f(3)(5), C()(5), etc.
        if isinstance(node.func, ast.Call):
            result = self._emit_call_on_call(node)
            if result is not None:
                return result
        # Subscript call: funcs[0](10), callbacks[i](x), etc.
        # The subscript evaluates to a function pointer or closure pointer;
        # dispatch through call_ptr which auto-detects closures.
        if isinstance(node.func, ast.Subscript):
            callee = self._emit_expr_value(node.func)
            callee = self._ensure_ptr(callee)
            n_args = len(node.args)
            if n_args == 0:
                return self.builder.call(self.runtime["call_ptr0"], [callee])
            elif n_args == 1:
                a = self._emit_expr_value(node.args[0])
                # Set arg tag so callee knows the argument type
                tag0, _ = self._bare_to_tag_data(a, node.args[0])
                self.builder.call(self.runtime["set_arg_tag"],
                                  [ir.Constant(i32, 0), ir.Constant(i32, tag0)])
                if isinstance(a.type, ir.PointerType):
                    a = self.builder.ptrtoint(a, i64)
                elif isinstance(a.type, ir.IntType) and a.type.width != 64:
                    a = self.builder.zext(a, i64)
                return self.builder.call(
                    self.runtime["call_ptr1"], [callee, a])
            elif n_args == 2:
                a1 = self._emit_expr_value(node.args[0])
                a2 = self._emit_expr_value(node.args[1])
                # Set arg tags so callee knows argument types
                tag0, _ = self._bare_to_tag_data(a1, node.args[0])
                tag1, _ = self._bare_to_tag_data(a2, node.args[1])
                self.builder.call(self.runtime["set_arg_tag"],
                                  [ir.Constant(i32, 0), ir.Constant(i32, tag0)])
                self.builder.call(self.runtime["set_arg_tag"],
                                  [ir.Constant(i32, 1), ir.Constant(i32, tag1)])
                if isinstance(a1.type, ir.PointerType):
                    a1 = self.builder.ptrtoint(a1, i64)
                if isinstance(a2.type, ir.PointerType):
                    a2 = self.builder.ptrtoint(a2, i64)
                return self.builder.call(
                    self.runtime["call_ptr2"], [callee, a1, a2])
            else:
                # 3+ args: pack into list
                args_list = self.builder.call(self.runtime["list_new"], [])
                for arg_node in node.args:
                    v = self._emit_expr_value(arg_node)
                    tag, data = self._bare_to_tag_data(v, arg_node)
                    self._rt_call("list_append_fv",
                                  [args_list, ir.Constant(i32, tag), data])
                return self.builder.call(
                    self.runtime["closure_call_list"], [callee, args_list])
        # Try indirect function pointer call
        if isinstance(node.func, ast.Name) and node.func.id in self.variables:
            result = self._try_indirect_func_call(node)
            if result is not None:
                return result
            return self._emit_closure_call(node)
        # Phase 4: unknown call expression → bridge fallback
        return self._bridge_fallback_expr(
            node, f"unsupported call expression: {type(node.func).__name__}")

    def _emit_builtin_map(self, node: ast.Call) -> ir.Value:
        """Emit map(func, iterable) or map(func, iter1, iter2) as an inline loop.

        Emits a new list and iterates the input, calling func on each element
        and appending the result with proper FpyValue tagging. This handles
        functions that return different types (str, int, float, etc.) unlike
        the old list_map_int which hardcoded INT tags.
        """
        # ── Two-iterable map: map(func, seq1, seq2) ──────────────
        if len(node.args) == 3:
            return self._emit_builtin_map_two(node)

        fn_node = node.args[0]
        seq = self._emit_expr_value(node.args[1])
        result = self.builder.call(self.runtime["list_new"], [])
        length = self._rt_call("list_length", [seq])

        idx_alloca = self._create_entry_alloca(i64, "map.idx")
        self.builder.store(ir.Constant(i64, 0), idx_alloca)

        cond_block = self._new_block("map.cond")
        body_block = self._new_block("map.body")
        end_block = self._new_block("map.end")

        self.builder.branch(cond_block)
        self.builder.position_at_end(cond_block)
        idx = self.builder.load(idx_alloca)
        cond = self.builder.icmp_signed("<", idx, length)
        self.builder.cbranch(cond, body_block, end_block)

        self.builder.position_at_end(body_block)
        idx = self.builder.load(idx_alloca)
        # Get element as bare value (int for int lists, str for str lists)
        elem_tag_a = self._create_entry_alloca(i32, "map.etag")
        elem_data_a = self._create_entry_alloca(i64, "map.edata")
        self._rt_call("list_get_fv",
                          [seq, idx, elem_tag_a, elem_data_a])
        elem_data = self.builder.load(elem_data_a)

        # Call the function on the element
        # Determine what the function is and how to call it
        if isinstance(fn_node, ast.Name) and fn_node.id == "str":
            # str(x) — dispatch by element type: int → int_to_str,
            # float → float_to_str, str → passthrough
            elem_tag = self.builder.load(elem_tag_a)
            is_float = self.builder.icmp_unsigned(
                "==", elem_tag, ir.Constant(i32, FPY_TAG_FLOAT))
            str_res_a = self._create_entry_alloca(i8_ptr, "map.sres")
            sf_bb = self._new_block("map.str.float")
            chks_bb = self._new_block("map.str.chks")
            ss_bb = self._new_block("map.str.str")
            si_bb = self._new_block("map.str.int")
            sm_bb = self._new_block("map.str.merge")
            self.builder.cbranch(is_float, sf_bb, chks_bb)
            # Float → float_to_str
            self.builder.position_at_end(sf_bb)
            f_val = self.builder.bitcast(elem_data, double)
            fs = self.builder.call(self.runtime["float_to_str"], [f_val])
            self.builder.store(fs, str_res_a)
            self.builder.branch(sm_bb)
            # Check if string
            self.builder.position_at_end(chks_bb)
            is_str_elem = self.builder.icmp_unsigned(
                "==", elem_tag, ir.Constant(i32, FPY_TAG_STR))
            self.builder.cbranch(is_str_elem, ss_bb, si_bb)
            # String → passthrough
            self.builder.position_at_end(ss_bb)
            self.builder.store(self.builder.inttoptr(elem_data, i8_ptr),
                               str_res_a)
            self.builder.branch(sm_bb)
            # Int → int_to_str
            self.builder.position_at_end(si_bb)
            is_val = self.builder.call(self.runtime["int_to_str"],
                                       [elem_data])
            self.builder.store(is_val, str_res_a)
            self.builder.branch(sm_bb)
            self.builder.position_at_end(sm_bb)
            str_val = self.builder.load(str_res_a)
            self.builder.call(self.runtime["list_append_fv"],
                              [result, ir.Constant(i32, FPY_TAG_STR),
                               self.builder.ptrtoint(str_val, i64)])
        elif isinstance(fn_node, ast.Name) and fn_node.id == "int":
            # int(x) — convert based on element type: str → parse,
            # float → truncate, int → passthrough
            elem_tag = self.builder.load(elem_tag_a)
            is_str = self.builder.icmp_unsigned(
                "==", elem_tag, ir.Constant(i32, FPY_TAG_STR))
            int_data_a = self._create_entry_alloca(i64, "map.idata")
            s_bb = self._new_block("map.int.str")
            chk_f_bb = self._new_block("map.int.chkf")
            fc_bb = self._new_block("map.int.fconv")
            p_bb = self._new_block("map.int.pass")
            m_bb = self._new_block("map.int.merge")
            self.builder.cbranch(is_str, s_bb, chk_f_bb)
            # String → parse to int
            self.builder.position_at_end(s_bb)
            str_ptr = self.builder.inttoptr(elem_data, i8_ptr)
            parsed = self._rt_call("str_to_int", [str_ptr])
            self.builder.store(parsed, int_data_a)
            self.builder.branch(m_bb)
            # Check if float
            self.builder.position_at_end(chk_f_bb)
            is_float = self.builder.icmp_unsigned(
                "==", elem_tag, ir.Constant(i32, FPY_TAG_FLOAT))
            self.builder.cbranch(is_float, fc_bb, p_bb)
            # Float → truncate to int
            self.builder.position_at_end(fc_bb)
            f_val = self.builder.bitcast(elem_data, double)
            i_val = self.builder.fptosi(f_val, i64)
            self.builder.store(i_val, int_data_a)
            self.builder.branch(m_bb)
            # Int → passthrough
            self.builder.position_at_end(p_bb)
            self.builder.store(elem_data, int_data_a)
            self.builder.branch(m_bb)
            self.builder.position_at_end(m_bb)
            self.builder.call(self.runtime["list_append_fv"],
                              [result, ir.Constant(i32, FPY_TAG_INT),
                               self.builder.load(int_data_a)])
        elif isinstance(fn_node, ast.Name) and fn_node.id == "float":
            # Convert int elements to float; keep float elements as-is
            elem_tag = self.builder.load(elem_tag_a)
            is_float_tag = self.builder.icmp_unsigned(
                "==", elem_tag, ir.Constant(i32, FPY_TAG_FLOAT))
            float_data_a = self._create_entry_alloca(i64, "map.fdata")
            f_bb = self._new_block("map.float.already")
            i_bb = self._new_block("map.float.conv")
            m_bb = self._new_block("map.float.merge")
            self.builder.cbranch(is_float_tag, f_bb, i_bb)
            # Already float — keep data as-is
            self.builder.position_at_end(f_bb)
            self.builder.store(elem_data, float_data_a)
            self.builder.branch(m_bb)
            # Int → convert to float
            self.builder.position_at_end(i_bb)
            f_val = self.builder.sitofp(elem_data, double)
            f_bits = self.builder.bitcast(f_val, i64)
            self.builder.store(f_bits, float_data_a)
            self.builder.branch(m_bb)
            self.builder.position_at_end(m_bb)
            self.builder.call(self.runtime["list_append_fv"],
                              [result, ir.Constant(i32, FPY_TAG_FLOAT),
                               self.builder.load(float_data_a)])
        else:
            # General case: get function pointer and call via call_ptr1
            # (which auto-detects closures via magic number)
            fn_ptr = self._get_unary_func_ptr(fn_node, node)
            mapped = self.builder.call(
                self.runtime["call_ptr1"], [fn_ptr, elem_data])
            # Infer result tag from the function
            if isinstance(fn_node, ast.Lambda):
                # Lambda body type determines the tag
                body = fn_node.body
                if (isinstance(body, ast.Compare)
                        or isinstance(body, ast.BoolOp)):
                    tag = FPY_TAG_BOOL
                elif isinstance(body, ast.JoinedStr):
                    tag = FPY_TAG_STR
                elif (isinstance(body, ast.Constant)
                      and isinstance(body.value, str)):
                    tag = FPY_TAG_STR
                elif (isinstance(body, ast.Constant)
                      and isinstance(body.value, float)):
                    tag = FPY_TAG_FLOAT
                elif (isinstance(body, ast.Call)
                      and isinstance(body.func, ast.Attribute)):
                    # Method call: check if it's a known string method
                    _str_ret_methods = {
                        "upper", "lower", "strip", "lstrip", "rstrip",
                        "replace", "capitalize", "title", "swapcase",
                        "join", "center", "ljust", "rjust", "zfill",
                        "encode", "format", "removeprefix", "removesuffix",
                    }
                    if body.func.attr in _str_ret_methods:
                        tag = FPY_TAG_STR
                    elif body.func.attr in ("split", "sorted"):
                        tag = FPY_TAG_LIST
                    else:
                        tag = FPY_TAG_INT
                else:
                    tag = FPY_TAG_INT
            elif (isinstance(fn_node, ast.Name)
                    and fn_node.id in self._user_functions):
                info = self._user_functions[fn_node.id]
                _rtk = self._tag_kind(info.ret_tag)
                if _rtk == VKind.STR:
                    tag = FPY_TAG_STR
                elif _rtk == VKind.FLOAT:
                    tag = FPY_TAG_FLOAT
                else:
                    tag = FPY_TAG_INT
            else:
                tag = FPY_TAG_INT
            self.builder.call(self.runtime["list_append_fv"],
                              [result, ir.Constant(i32, tag), mapped])

        next_idx = self.builder.add(
            self.builder.load(idx_alloca), ir.Constant(i64, 1))
        self.builder.store(next_idx, idx_alloca)
        self.builder.branch(cond_block)

        self.builder.position_at_end(end_block)
        return result


    def _emit_builtin_map_two(self, node: ast.Call) -> ir.Value:
        """Emit map(func, seq1, seq2) — two-iterable map."""
        fn_node = node.args[0]
        seq1 = self._emit_expr_value(node.args[1])
        seq2 = self._emit_expr_value(node.args[2])
        result = self.builder.call(self.runtime["list_new"], [])
        len1 = self._rt_call("list_length", [seq1])
        len2 = self._rt_call("list_length", [seq2])
        # min(len1, len2) — Python map stops at the shortest iterable
        use_len2 = self.builder.icmp_signed("<", len2, len1)
        length = self.builder.select(use_len2, len2, len1)

        idx_alloca = self._create_entry_alloca(i64, "map2.idx")
        self.builder.store(ir.Constant(i64, 0), idx_alloca)

        cond_block = self._new_block("map2.cond")
        body_block = self._new_block("map2.body")
        end_block = self._new_block("map2.end")

        self.builder.branch(cond_block)
        self.builder.position_at_end(cond_block)
        idx = self.builder.load(idx_alloca)
        cond = self.builder.icmp_signed("<", idx, length)
        self.builder.cbranch(cond, body_block, end_block)

        self.builder.position_at_end(body_block)
        idx = self.builder.load(idx_alloca)
        # Get elements from both lists
        tag1_a = self._create_entry_alloca(i32, "map2.t1")
        data1_a = self._create_entry_alloca(i64, "map2.d1")
        tag2_a = self._create_entry_alloca(i32, "map2.t2")
        data2_a = self._create_entry_alloca(i64, "map2.d2")
        self._rt_call("list_get_fv", [seq1, idx, tag1_a, data1_a])
        self._rt_call("list_get_fv", [seq2, idx, tag2_a, data2_a])
        elem1 = self.builder.load(data1_a)
        elem2 = self.builder.load(data2_a)

        # Call the function with two arguments
        if isinstance(fn_node, ast.Name) and fn_node.id in self._user_functions:
            info = self._user_functions[fn_node.id]
            if info.uses_fv_abi:
                # Wrap both args as FpyValue, call the function, unwrap
                tag1 = self.builder.load(tag1_a)
                tag2 = self.builder.load(tag2_a)
                fv1 = self.builder.insert_value(
                    ir.Constant(fpy_val, ir.Undefined), tag1, 0)
                fv1 = self.builder.insert_value(fv1, elem1, 1)
                fv2 = self.builder.insert_value(
                    ir.Constant(fpy_val, ir.Undefined), tag2, 0)
                fv2 = self.builder.insert_value(fv2, elem2, 1)
                ret_fv = self.builder.call(info.func, [fv1, fv2])
                mapped = self.builder.extract_value(ret_fv, 1)
            else:
                # Bare ABI: i64(i64, i64)
                mapped = self.builder.call(info.func, [elem1, elem2])
            # Determine result tag
            _rtk = self._tag_kind(info.ret_tag)
            if _rtk == VKind.STR:
                tag = FPY_TAG_STR
            elif _rtk == VKind.FLOAT:
                tag = FPY_TAG_FLOAT
            else:
                tag = FPY_TAG_INT
        elif isinstance(fn_node, ast.Lambda):
            # Lambda with two args: emit inline and use call_ptr2
            fn_ptr = self._get_binary_func_ptr_lambda(fn_node, node)
            mapped = self.builder.call(
                self.runtime["call_ptr2"], [fn_ptr, elem1, elem2])
            tag = FPY_TAG_INT  # default; refine from body if needed
            body = fn_node.body
            if isinstance(body, ast.Compare) or isinstance(body, ast.BoolOp):
                tag = FPY_TAG_BOOL
            elif isinstance(body, ast.Constant) and isinstance(body.value, str):
                tag = FPY_TAG_STR
            elif isinstance(body, ast.Constant) and isinstance(body.value, float):
                tag = FPY_TAG_FLOAT
        else:
            # Fallback: use call_ptr2 with a generic function pointer
            fn_ptr = self._get_unary_func_ptr(fn_node, node)
            mapped = self.builder.call(
                self.runtime["call_ptr2"], [fn_ptr, elem1, elem2])
            tag = FPY_TAG_INT

        self.builder.call(self.runtime["list_append_fv"],
                          [result, ir.Constant(i32, tag), mapped])

        next_idx = self.builder.add(
            self.builder.load(idx_alloca), ir.Constant(i64, 1))
        self.builder.store(next_idx, idx_alloca)
        self.builder.branch(cond_block)

        self.builder.position_at_end(end_block)
        return result

    def _get_binary_func_ptr_lambda(self, lam: ast.Lambda, node: ast.AST) -> ir.Value:
        """Emit a binary lambda `lambda a, b: <expr>` as an i64(i64, i64) func."""
        lam_name = f"fastpy.inline_lambda2.{self._block_counter}"
        self._block_counter += 1
        p1_name = lam.args.args[0].arg
        p2_name = lam.args.args[1].arg
        func_type = ir.FunctionType(i64, [i64, i64])
        func = ir.Function(self.module, func_type, name=lam_name)
        func.args[0].name = p1_name
        func.args[1].name = p2_name

        saved_func = self.function
        saved_builder = self.builder
        saved_vars = dict(self.variables)

        self.function = func
        entry = func.append_basic_block("entry")
        self.builder = _SafeIRBuilder(entry)

        # Map parameter names to function args
        self.variables[p1_name] = func.args[0]
        self.variables[p2_name] = func.args[1]

        body_val = self._emit_expr_value(lam.body)
        if isinstance(body_val.type, ir.IntType) and body_val.type.width != 64:
            body_val = self.builder.sext(body_val, i64)
        elif isinstance(body_val.type, ir.DoubleType):
            body_val = self.builder.bitcast(body_val, i64)
        elif isinstance(body_val.type, ir.PointerType):
            body_val = self.builder.ptrtoint(body_val, i64)
        elif isinstance(body_val.type, ir.LiteralStructType):
            body_val = self.builder.extract_value(body_val, 1)
        self.builder.ret(body_val)

        self.function = saved_func
        self.builder = saved_builder
        self.variables = saved_vars
        return self.builder.bitcast(func, i8_ptr)

    # ── Module dispatch handlers (Phase B1 extraction) ──────────────────

    def _emit_json_call(self, func_name, node):
        """json.dumps / json.loads"""
        if func_name == "dumps" and len(node.args) == 1 and not node.keywords:
            val = self._emit_expr_value(node.args[0])
            tag, data = self._bare_to_tag_data(val, node.args[0])
            # fastpy_json_dumps_fv always returns a fresh owned (+1) FpyString
            # (fpy_str_copy) — register it for release at the statement
            # boundary (Model 2).
            return self._register_owned_str_ptr(
                self.builder.call(self.runtime["json_dumps"],
                                  [ir.Constant(i32, tag), data]))
        elif func_name == "loads" and len(node.args) == 1:
            arg = self._emit_expr_value(node.args[0])
            arg = self._ensure_ptr(arg)
            out_tag = self._create_entry_alloca(i32, "json.tag")
            out_data = self._create_entry_alloca(i64, "json.data")
            self.builder.call(self.runtime["json_loads"],
                              [arg, out_tag, out_data])
            tag_val = self.builder.load(out_tag)
            data_val = self.builder.load(out_data)
            # Return FpyValue — json.loads can return any type (int, str,
            # list, dict, bool, None) depending on the input JSON.
            fv = ir.Constant(fpy_val, ir.Undefined)
            fv = self.builder.insert_value(fv, tag_val, 0)
            fv = self.builder.insert_value(fv, data_val, 1)
            return fv
        return None

    def _emit_os_call(self, func_name, node):
        """os.getcwd / os.listdir / os.getenv + os.path functions"""
        if func_name == "getcwd" and len(node.args) == 0:
            return self.builder.call(self.runtime["os_getcwd"], [])
        elif func_name == "getpid" and len(node.args) == 0:
            # os.getpid() -> bare i64 PID (on SlateOS a real SYS_PROCESS_ID
            # syscall via posix getpid()).
            return self.builder.call(self.runtime["os_getpid"], [])
        elif func_name == "getppid" and len(node.args) == 0:
            # os.getppid() -> bare i64 parent PID (on SlateOS a real
            # SYS_PROCESS_PARENT_ID syscall via posix getppid()).
            return self.builder.call(self.runtime["os_getppid"], [])
        elif func_name == "gettid" and len(node.args) == 0:
            # os.gettid() -> bare i64 kernel task ID (on SlateOS a real
            # SYS_TASK_ID syscall via posix gettid()).
            return self.builder.call(self.runtime["os_gettid"], [])
        elif func_name == "getuid" and len(node.args) == 0:
            # os.getuid() -> bare i64 real uid (on SlateOS a real
            # SYS_PROCESS_GET_CREDENTIALS syscall via posix getuid()).
            return self.builder.call(self.runtime["os_getuid"], [])
        elif func_name == "getgid" and len(node.args) == 0:
            # os.getgid() -> bare i64 real gid (on SlateOS a real
            # SYS_PROCESS_GET_CREDENTIALS syscall via posix getgid()).
            return self.builder.call(self.runtime["os_getgid"], [])
        elif func_name in ("setuid", "setgid") and len(node.args) == 1:
            # os.setuid(uid)/os.setgid(gid) -> bare i64 status (0 ok, -1 EPERM).
            # On SlateOS posix setuid()/setgid() run the userspace
            # CAP_SETUID/CAP_SETGID + identity check and, if allowed, issue the
            # real SYS_PROCESS_SET_CREDENTIALS syscall that mutates the kernel
            # process credentials — a distinct kernel path (the
            # process-credentials table) from the read-only getuid/getgid.
            def _id_i64(v):
                if (isinstance(v.type, ir.LiteralStructType)
                        and v.type == fpy_val):
                    return self.builder.extract_value(v, 1)
                if isinstance(v.type, ir.PointerType):
                    return self.builder.ptrtoint(v, i64)
                if isinstance(v.type, ir.DoubleType):
                    return self.builder.fptosi(v, i64)
                if isinstance(v.type, ir.IntType) and v.type.width != 64:
                    return self.builder.zext(v, i64)
                return v
            idv = _id_i64(self._emit_expr_value(node.args[0]))
            rt_name = "os_setuid" if func_name == "setuid" else "os_setgid"
